(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["tr"] = {"ui":{"skip":"İçeriğe geç","back":"← AI-gile'a dön","lang.button":"Dil: {name}","lang.dialog":"Bir dil seç","lang.search":"Dil ara","lang.none":"Eşleşen dil yok","lang.notYet":"{name} henüz çevrilmedi","theme.aria":"Açık ve koyu tema arasında geçiş yap","theme.toLight":"Açık temaya geç","theme.toDark":"Koyu temaya geç","words.underline":"Bu kelimelerin altını sayfada çiz","words.underlineHelp":"Ne anlama geldiğini görmek için noktalı bir kelimenin üzerine gel ya da dokun.","index.title":"AI-gile: yapay zekâ yazılım ekibin, tek bir panoda","index.description":"AI-gile, yapay zekâ ile kod yazan ekipler için bir kanban panosu. Sen uyurken çalışırlar; sana karar verecek, deneyecek ve onaylayacak kısa bir yığın kalır.","hero.logoAlt":"AI-gile pano simgesi","hero.h1.html":"Yapay zekâ yazılım ekibin, tek bir&nbsp;panoda.","hero.alpha":"🐣 Kapalı ön alfa","hero.alphaTitle":"Erken ve bitmemiş: denediğin için sağ ol!","hero.lede":"Sen uyurken yaparlar. Sabah kısa bir yığınla uyanırsın: birkaç soru, birkaç denenecek şey, bir iki mor elmas. Tıkla, onayla, kahvene dön.","dl.windows":"Windows uygulaması","dl.browser":"Tarayıcında çalıştır","dl.soon":"Yakında","dl.notify":"🔔 Açılınca haber ver","dl.notifySmall":"Alfa ya da beta","hero.secondary":"Çevik, ama ekibin ayaküstü toplantı kahvesine hiç ihtiyacı yok. (Yine de toplantı yaparlar.)","pitch.h2":"AI-gile, istediğin kadar sözcükle","pitch.lede":"Bir uzunluk seç, tek sözcükten 144'e kadar. Her uzunluk kendi boyuna göre yazılmış ayrı bir anlatım. Kaydırıcıyı sürükle ya da ok tuşlarını kullan.","pitch.rangeLabel":"Sözcük olarak uzunluk","pitch.dice":"🎲 başka bir sürüm","pitch.words.one":"{n} sözcük","pitch.words.other":"{n} sözcük","pitch.letters.one":"{n} harf","pitch.letters.other":"{n} harf","pitch.chars.one":"{n} karakter","pitch.chars.other":"{n} karakter","count.line.html.one":"Şu an panoda {n} kart var","count.line.html.other":"Şu an panoda {n} kart var","features.aria":"Ne yapar","f.pile.h":"Senin için tek yığın","f.pile.html":"<b>Senin için</b>, bütün projelerde sende bekleyen her şeyi toplar: sorular, denenecek şeyler, yalnızca bir insanın yapabileceği işler. Sıran sırada ne olduğunu ve ne kadar süreceğini söyler.","f.sleep.h":"Sen uyurken çalışan ekipler","f.sleep.p":"Her projenin bir lideri ve bir yapay zekâ ajanı ekibi var. Bir karta yorum yaz, ekip uyanır, işi yapar ve yorgun bir insanın izleyebileceği adımlarla geri verir.","f.tester.h":"Önce bir yapay zekâ test edici bakar","f.tester.p":"Sana ulaşmadan önce bir test edici, uygulamanın bir kopyasında adımları izler ve gördüğünü ekran görüntüsüyle gösterir. Geçenlere göz at, tek tıkla onayla.","f.proof.h":"Söz değil, kanıt","f.proof.p":"Her teslim neyin değiştiğini gösterir: dosyaları, farkı, ekran görüntülerini. Bitti mi diye her uygulamayı tek tek açmak yok.","f.chat.h":"Liderlerinle sohbet et","f.chat.p":"Discord tarzı bir şerit: proje başına bir simge, sana ihtiyaç olan yerde mor elmaslar. Bir lidere fikrini yaz; kartlara ve bir plana çevirir, yanında bir ✅ Başla düğmesiyle.","f.tidy.h":"Kendi kendini toplar","f.tidy.p":"İlgili kartlar tek kartta birleşir, karışık başlıklar düzelir, bir token denetimi kodu sade tutar. Arasında geçiş yapılacak şey az, düşünülecek şey az.","f.private.h":"Senin, senin bilgisayarında","f.private.li1":"Pano kendi makinende çalışır ve yalnızca sana yanıt verir.","f.private.li2":"İnsanlar arasındaki özel mesajlar uçtan uca şifrelidir.","f.private.li3":"Hesap yok, izleyici yok, çerez yok.","f.lang.h":"Senin dilinde","f.lang.p":"Hollandacadan, Galceden ve Japoncadan korsan, Yoda ve Klingon diline kadar 120'den fazla dil; yazılımcı sözcükleri için de tek dokunuşla İngilizceye dönüş var.","tl.aria":"İlk konuşmadan yol haritasına zaman çizelgesi","tl.h2":"İlk sohbetten sıradakine","tl.lede":"Gerçek tarihler ve saatler, kendi saat diliminde. Bugünden sonrası plan; söz verilmiş tarih yok.","tl.today":"Bugün","tl.planned":"planlandı","tl.cards.one":"{n} kart","tl.cards.other":"{n} kart","join.h2":"Sen de katıl","join.lede":"AI-gile'ı küçük bir insan ve çok sayıda sabırlı ajan yapıyor. Şimdilik özel: arkadaşlarla kapalı bir alfada. Açıldığında denemek ister misin?","join.btn":"İlgimi kaydet","join.small":"Sana e-posta atarız, başka bir şey yok","footer.tag":"AI-gile. İzleyici yok, çerez yok, ayaküstü kahve yok.","footer.licence":"İş lisansı","footer.status":"Durum","footer.privacy":"Neleri saklıyoruz","form.sending":"Gönderiliyor…","form.failed":"Olmadı: biraz sonra tekrar dene.","form.offline":"AI-gile'a ulaşılamadı: biraz sonra tekrar dene.","form.keep":"Bunu yalnızca sana yanıt vermek için kullanırız, sonra sileriz. İzleyici yok, çerez yok.","form.keepLink":"Neleri saklıyoruz","interest.title":"AI-gile: alfa açılınca haber ver","interest.description":"AI-gile'ın kapalı alfası ya da betası açılınca haberdar olmak için e-postanı bırak.","interest.h1":"🔔 Açılınca haber ver","interest.lede":"AI-gile kapalı ön alfada. E-postanı bırak; sana yer olduğunda bir kez yazarız.","interest.email":"E-postan","interest.which":"Hangi test?","interest.alpha":"Kapalı alfa: erken, pürüzlü, çok değişiklik","interest.beta":"Beta: daha oturmuş, daha geç","interest.both":"Hangisi önce gelirse","interest.submit":"Beni listeye yaz","interest.thanks":"Teşekkürler! Listedesin.","licence.title":"AI-gile: iş lisansı","licence.description":"AI-gile'ı işinde mi kullanıyorsun? Ücretsiz iş lisansı için başvur.","licence.h1":"📜 İş lisansı","licence.lede":"AI-gile'ı işte mi kullanıyorsun? Kim olduğunu ve ne yaptığını anlat. Biraz iyilik yapıyorsa lisans ücretsiz.","licence.company":"Şirket","licence.website":"Web sitesi","licence.what":"Ne yapıyorsun","licence.how":"Dünyaya nasıl yardım ediyor","licence.email":"E-posta","licence.submit":"Başvur","licence.thanks":"Teşekkürler! E-postayla yanıtlarız.","status.title":"AI-gile durumu","status.h1":"AI-gile durumu","status.quiet":"Her şey sakin","status.intro":"AI-gile şu an çalışıyor mu? Bu sayfa web sitesini, pano paylaşımını, aramaları ve indirmeyi 5 dakikada bir kontrol eder.","status.up":"Çalışıyor ({ms} ms'de yanıt verdi)","status.slow":"Son kontrole yanıt vermedi, yeniden deneniyor","status.down":"Çalışmıyor: son iki kontrole yanıt vermedi","status.svc.web":"Web sitesi","status.svc.web.offers":"Bu site: AI-gile'ın ne olduğu ve haber ver formu","status.svc.boards":"Pano paylaşımı","status.svc.boards.offers":"Herkese açık panolar, arkadaşlar arası mesajlar ve davetler","status.svc.calls":"Aramalar","status.svc.calls.offers":"AI-gile'da sesli, görüntülü arama ve ekran paylaşımı","status.svc.download":"İndirme","status.svc.download.offers":"Windows yükleyicisi ve davet bağlantıları","status.checking":"Bakılıyor…","status.offline":"Durum hizmetine şu an ulaşılamıyor (yeniden deneniyor)","status.updated":"güncellendi: {ago}","status.justNow":"az önce","status.min":"{n} dk önce","status.hours":"{n} sa önce","status.days":"{n} g önce","privacy.title":"AI-gile: neleri saklıyoruz","privacy.h1":"Neleri saklıyoruz","privacy.lede":"Kısacası: yalnızca bize gönderdiklerin, o da uzun süre değil.","privacy.only":"Yalnızca bize gönderdiklerin: bir forma yazdıkların, örneğin e-postan. Seninle ilgili başka hiçbir şey.","privacy.sealed":"Sunucumuz okuyamasın diye mühürlenir: daha tarayıcından çıkmadan (eski bir tarayıcıdaysa ulaştığı anda). Onu yalnızca kendi panomuz açabilir.","privacy.server":"Panomuza ulaşır ulaşmaz sunucudan silinir. 30 gün sonra hâlâ orada duran her şey de zaten silinir.","privacy.board":"Panomuzda yalnızca sana yanıt verene kadar tutarız, sonra oradan da sileriz.","privacy.none":"İzleyici yok, çerez yok, analiz yok.","privacy.local":"Dil ve açık ya da koyu tema seçimin kendi tarayıcında kalır. Asla bize gönderilmez.","privacy.ask":"Daha erken silinsin mi istiyorsun? E-postamıza yanıt verip bunu söylemen yeterli.","live.h2":"Nasıl inşa edildiğini canlı izleyin","live.caption":"Her kart gizli: işin biçimini görüyorsunuz, sözcükleri değil.","live.watching.one":"canlı: {n} izliyor","live.watching.other":"canlı: {n} izliyor","live.last.now":"Son kart az önce taşındı","live.last.min.one":"Son kart {n} dk önce taşındı","live.last.min.other":"Son kart {n} dk önce taşındı","live.last.hour.one":"Son kart {n} saat önce taşındı","live.last.hour.other":"Son kart {n} saat önce taşındı","live.last.day.one":"Son kart {n} gün önce taşındı","live.last.day.other":"Son kart {n} gün önce taşındı","live.offline":"Canlı pano kısa bir mola veriyor. Birazdan tekrar uğrayın.","live.cols":"Backlog|Yapılacak|Sürüyor|Ekip kontrol ediyor|Senin test etmen için|Ekip için|Bitti"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Robotlar.","Devredildi."]},{"n":2,"texts":["Robot kanban.","Düzenli ajanlar.","Fikirler, yapıldı."]},{"n":3,"texts":["Robotlar için kanban.","Fikirler özelliğe dönüşür.","Ücretsiz ajan kanbanı."]},{"n":5,"texts":["Ajanların çalıştırdığı kanban panosu.","Sen kart yaz. Ajanlar yapsın.","Ücretsiz, yerel, test edilmiş, biraz komik."]},{"n":8,"texts":["Yapay zekâ ajanlarının çalıştığı ücretsiz bir kanban panosu.","Fikri yaz. Ajanlar yapar. Sen onaylarsın.","Bir insan ve sabırlı robotlar için çevik yöntem."]},{"n":13,"texts":["Bilgisayarındaki bir kanban panosu; kartları yapay zekâ ajanları alıp işler.","Bir fikir yaz. Ajan ekibi yapar. Bir test edici kontrol eder.","Ücretsiz, hesapsız, izleyicisiz: bir pano, birkaç robot ve işin başındaki sen."]},{"n":21,"texts":["AI-gile, yapay zekâ kodlama ajanlarıyla çalışmak için bir kanban panosu. Kartları onlar alır; sen denersin ve onaylarsın.","Her projenin bir lideri ve bir ajan ekibi var. İstediğin karta yorum yaz, ekip hemen işe koyulsun.","Kendi bilgisayarında çalışan, ücretsiz, kişisel bir yapılacaklar panosu. Çalışanlar robot, ama evet ya da hayır diyen yine sen."]},{"n":34,"texts":["Fikirlerini bir panoya koyarsın. Yapay zekâ ajanlarından oluşan bir ekip onları çalışan özelliklere çevirir, test eder ve denemen için adımlarla birlikte sana geri verir. Sen demeden hiçbir şey bitmiş sayılmaz.","AI-gile, Rich'in bugün yönettiği ajanların büyük yardımıyla evde yaptığı bir kanban panosu. Ücretsiz, senin bilgisayarında çalışıyor ve satılmıyor; yalnızca arkadaşlarla paylaşılıyor, hiç kimseden de bir kuruş istenmiyor.","Sıradan bir kanban panosu düşün: Backlog'dan Bitti'ye uzanan sütunlar var, ama kartları yapay zekâ ajanları alıyor. Nasıl gittiğini haber verirler, takılınca soru sorarlar ve her zaman senin onay işaretini beklerler."]},{"n":55,"texts":["AI-gile, ekibi yapay zekâ ajanlarından oluşan bir kanban panosu. Her projenin işi planlayan bir lideri ve işi yapan yardımcıları var. Bir özellik hazır olunca bir yapay zekâ test edici onu dener, ekran görüntüsü alır ve iş senin yığınına düşer. Onayla, ya da yorum yaz; yeniden çalışırlar.","Her şey bir kişinin aynı anda açık duran bir sürü yapay zekâ kodlama oturumunu karıştırmadan takip etme isteğiyle başladı, sonra gerçek bir panoya dönüştü. Makinende çalışır, hesap istemez ve izleyicisi yoktur. Arkadaşlar ve meraklılar için ücretsiz. Henüz bitmedi de; yani pürüzler ve ara sıra küçük sürprizler çıkabilir.","Dürüst anlatım şöyle: fikirleri yine sen bulacaksın, sonuçlara da yine sen bakacaksın. AI-gile bu ikisinin arasındaki her şeyi üstlenir: kartları sıralı tutar, sen bir yorum yazınca doğru ajanı uyandırır, tam olarak neyin değiştiğini gösterir ve bunların hepsini senin için kısacık, tek bir yığında toplar."]},{"n":89,"texts":["AI-gile, kendi bilgisayarında çalıştırdığın ücretsiz bir kanban panosu. İnsanlar yerine her projenin bir yapay zekâ ajanı ekibi var: fikirlerini kartlara ve bir plana çeviren bir lider, bu kartları öncelik sırasıyla alan yardımcılar. Bir şey yapılınca bir yapay zekâ test edici test adımlarını izler ve gördüğünü sana gösterir. Sonra Senin için yazan tek bir yığında bekler. Onaylarsın, ya da yorum yazarsın ve ekip bir kez daha dener. Sen olmadan hiçbir şey Bitti'ye varmaz.","Beklemeyebileceğin birkaç özellik de var. Bir gece nöbetçisi, sen uyurken senden yanıt gerektirmeyen kartları seçip Yapılacak sütununu dolu tutar. Bir token sayacı ajanların bugün ve bu hafta ne kadar harcadığını gösterir; Token Yok Modu ise onlara harcamayı bırakmalarını söyler. Arkadaşlarına mesaj yazabilirsin ve özel mesajlar uçtan uca şifrelidir. Pano yaklaşık 120 dil konuşur; Felemenkçe, Flamanca, korsan ve Klingon bile var. Hiçbiri tek kuruş tutmuyor, üstelik kimse sana bir şey satmaya da çalışmıyor.","AI-gile küçük ve kişisel bir proje, bir şirket değil. Rich birkaç yapay zekâ kodlama projesine göz kulak olmak istiyordu, ama bunun için her uygulamayı tek tek açıp bakmak istemiyordu. Bu yüzden ajanlarla birlikte bunun için bir pano yaptılar, sonra panonun geri kalanını da o panoyla yaptılar. Şimdi kapalı ön alfada: yani bir avuç arkadaş için çoğunlukla çalışıyor. Fiyat sayfası yok, bülten yok, büyüme planı da yok. Sana faydalı geliyorsa, biraz daha açıldığında denemek için sorabilirsin."]},{"n":144,"texts":["AI-gile, bir insan ve çok sayıda yapay zekâ ajanı için bir kanban panosu. Tamamen ücretsizdir ve kendi bilgisayarında çalışır. Projeleri eklersin; her projeye bir lider ve küçük bir ekip düşer. Liderle biraz Discord'daki gibi sohbet eder, bir fikri anlatırsın; lider onu kartlara ve bir plana çevirir, sonra senin Başla düğmesine basmanı bekler. Ekip kartları öncelik sırasına göre tek tek işler. Bunun için dil modelleri adına yapılmış basit bir komut satırı kullanır. Sana dönmeden önce bir yapay zekâ test edici, uygulamanın bir kopyasında adımları izler ve ekran görüntüsü ekler. Biten iş, değişen dosyalar ve farkla birlikte senin yığınına düşer. Onaylarsın ya da bir yorum bırakırsın; ekip uyanır ve yeniden dener. Bir kartı Bitti sütununa yalnızca sen taşıyabilirsin.","AI-gile ile kabaca bir gün şöyle geçer. Akşam birkaç yorum bırakırsın: bu düğme yanlış yerde, şu liste sıralı olsun, bir de koyu tema olabilir mi. Sonra yatmaya gidersin. Ajanlar yorumlarını okur, değişiklikleri yapar, hepsini test eder ve sana geri verir. Yapılacak sütunu boşalırsa gece nöbetçisi onu backlogdan, senden yanıt gerektirmeyen kartlarla yeniden doldurur. Sabah karşında kısa bir yığın durur: birkaç soru ve denenecek birkaç şey; her biri uykulu birinin bile izleyebileceği adımlarla ve işlediğini gösteren bir ekran görüntüsüyle gelir. Tek tek tıklar, iyileri onaylar, kalanları geri gönderirsin. Bir token sayacı bunların hepsinin neye mal olduğunu gösterir, sade geçecek haftalar için de Token Yok Modu hazırdır. Sonra kahvaltı edersin; ajanlar buna henüz yardım edemiyor, ne yazık ki.","Önce AI-gile'ın ne olmadığını söyleyeyim: bir girişim değil, satılık değil ve hiç kimse verilerini toplamıyor. Bilgisayarında çalışan, hesapsız, izleyicisiz ve çerezsiz, ücretsiz bir pano. Peki ne? Bütün yapay zekâ kodlama projelerini aynı anda gördüğün tek ve düzenli bir yer: kartları bir ajan ekibi yapar, kararları ise sen verirsin. İlgili kartları birleştirir, karışık başlıkları düzeltir ve kodun ne kadar sade kaldığına da göz kulak olur. Felemenkçeden ve Flamancadan korsan diline, hatta Klingon'a kadar yaklaşık 120 dil konuşur. Arkadaşlar birbirlerine özel ve şifreli mesajlar yazabilir. Onu Rich ile çok sayıda sabırlı ajan yaptı, çoğunlukla da kendi kendini kullanarak. Şimdilik kapalı ön alfada, yani yer yer pürüzlü, arada bir de şaşırtıcı. Eğlenceli geliyorsa kibarca iste; belki herkesten önce erkenden içeri girersin."]}],"quips":{"1":"Tek sözcük. Cesur. Belki fazla cesur.","3":"Üç sözcük. Çoğu ürün sayfasından zaten daha dürüst.","8":"Sekiz sözcük. Yine de bir ayaküstü toplantıdan kısa.","21":"Bu arada uzunluklar hikâye puanı. Tabii ki öyle.","55":"Elli beş sözcük. Sen okurken iki kart bitti.","144":"Bu en uzunu. 233 yok. Ajanlar yatmaya gitti."}},"timeline":{"first-idea.name":"İlk fikir","first-idea.line":"Tek satır kod yokken yapılan ilk konuşma.","first-board.name":"İlk pano","first-board.line":"Kendi yapımını izleyen bir pano: kartlar, sütunlar, sürükle bırak, projeler.","team-roles.name":"Ekip ve roller","team-roles.line":"Ajan profilleri, ekip şablonları, alanlar ve kimin ne yaptığı.","install.name":"Kurulum ve sürümler","install.line":"Bir arkadaşın kurabileceği zip, kendi kendine güncelleme, kanallar ve geri alma.","usage-saver.name":"Kullanım tasarrufu","usage-saver.line":"Çalıştırmaların maliyetini ölç, kodu sade tut, limitini koru.","friends.name":"Arkadaşlar ve paylaşım","friends.line":"Özel mesajlar, karıştırılmış bir aktarıcı, davetler, roller ve ortak projeler.","languages.name":"Diller","languages.line":"Her ekran metni bir dil dosyasında; önce Felemenkçe ve Flamanca.","ai-tester.name":"Yapay zekâ test edici","ai-tester.line":"Her teslimi önce bir test edici inceler ve gördüğünü gösterir.","website.name":"Web sitesi","website.line":"aigile.lol, tanıtım sayfası ve bu zaman çizelgesi.","streaming.name":"Sohbet ve yayın","streaming.line":"Discord, Twitch, OBS, yayıncı modu, GIF'ler ve emojiler.","no-ai.name":"Yapay zekâsız sürüm","no-ai.line":"Yapay zekâ kullanmadan kod yazanlar için bir pano ve herkese açık panolar.","night-watch.name":"Gece nöbeti","night-watch.line":"Bir nöbetçi ve Scrum Master, sen uyurken ekipleri işin başında tutar.","p-more.name":"Geri kalan her şey","p-more.line":"Sırasını bekleyen daha küçük fikirler.","p-android.name":"Telefon ve Android","p-android.line":"Panona telefondan ulaş, sonra yerel bir Android uygulaması.","p-release.name":"Alfa ve ötesi","p-release.line":"Kapalı alfa, canlı site, sonra beta.","p-languages.name":"Daha çok dil","p-languages.line":"Yüzden fazla dil ve öğrenenler için bir daldırma modu.","p-engines.name":"Daha çok yapay zekâ motoru","p-engines.line":"Ajan başına Claude, Codex ya da Gemini seç.","p-pro.name":"Profesyonel uygulama","p-pro.line":"Risk etiketleri, birleştirme kapıları, olay kartları ve korkuluklar.","p-self.name":"Seni kollamak","p-self.line":"Yorgunluk modu, kendine bakım hatırlatıcıları ve 4:20.","p-servers.name":"Sunucular ve ölçek","p-servers.line":"Genel sunucu ayarları, roller ve büyüme planı.","p-livestream.name":"Yayın ekstraları","p-livestream.line":"Twitch sohbeti, özel emojiler ve herkese açık canlı görünüm."},"words":{"button":"📖 Geliştirici terimleri","h":"📖 Words explained","intro":"The words you meet in AI-gile, in plain language: building it, changing it safely, keeping it running for the people who use it, and working as a team with AI.","search":"Bir terim ara…","none":"Eşleşen terim yok.","close":"Kapat","count":{"one":"{count} word","other":"{count} words"},"groups":[{"id":"build","name":"🛠️ Building it"},{"id":"change","name":"🔀 Changing it safely"},{"id":"run","name":"🛎️ Running a service"},{"id":"team","name":"🤝 Working as a team (and with AI)"}],"list":[{"id":"repo","g":"build","word":"Repo","text":"Projenin kod klasörü ve commit'lerin tüm geçmişi; genelde GitHub'da da tutulur.","also":["repository","depo"]},{"id":"branch","g":"build","word":"Branch","text":"Kodda ayrı bir çalışma hattı; böylece ana sürüme dokunmadan değişiklik yapılabilir.","also":["branch'ler","dal","dallar"]},{"id":"commit","g":"build","word":"Commit","text":"Kodun, neyin değiştiğine dair kısa bir notla kaydedilmiş anlık görüntüsü. İstediğin zaman ona geri dönebilirsin.","also":["commit'ler"]},{"id":"push","g":"build","word":"Push","text":"Kaydedilmiş anlık görüntüleri (commit'leri) bu bilgisayardan GitHub'a göndermek; böylece yedeklenir ve paylaşılır."},{"id":"merge","g":"build","word":"Merge","text":"Bir branch'in değişikliklerini ana sürüme geri katmak."},{"id":"pr","g":"build","word":"Pull request","text":"Bir branch'in değişikliklerinin kontrol edilip ana sürüme katılmasını istemek.","also":["PR"]},{"id":"refactor","g":"build","word":"Refactor","text":"Kodun yaptığı işi değiştirmeden düzenlemek: daha küçük dosyalar, daha net adlar, daha az tekrar."},{"id":"bug","g":"build","word":"Bug","text":"Olması gerektiği gibi çalışmayan bir şey.","also":["bug'lar","hata","hatalar"]},{"id":"test","g":"build","word":"Test","text":"Bitmiş bir işi, kabul etmeden önce istenileni yapıp yapmadığını görmek için denemek.","also":["testler"],"noTip":1},{"id":"qa","g":"build","word":"QA","text":"Short for quality assurance: the automatic checks that run before anything goes live. When QA is red, something failed, and it can’t go live until that is fixed.","also":["quality checks"]},{"id":"deploy","g":"change","word":"Deploy","text":"Yeni bir sürümü canlıya almak, örneğin insanların kullandığı bir sunucuya."},{"id":"release","g":"change","word":"Release","text":"A named bundle of finished work that goes live together, with short notes on what changed. 🚀 Releases writes the notes from the done cards.","also":["releases"]},{"id":"rollback","g":"change","word":"Roll back","text":"Going back to the last version that worked when a new one causes trouble. In AI-gile it makes a checklist of the undo steps written on each change.","also":["rollback","roll-back","rolled back"]},{"id":"live","g":"change","word":"Live","text":"The real version that people use, as opposed to a copy for trying things out. Developers also call it production.","also":["production"],"noTip":1},{"id":"change","g":"change","word":"Change","text":"A planned change to something people rely on, written down first: what, why, the risk, when, and how to undo it. Start one with 🔀 Raise a change.","also":["change request","change requests"],"noTip":1},{"id":"risk","g":"change","word":"Risk","text":"Something that could go wrong, scored on how likely and how bad it would be. ⚠️ Risks keeps them in one list, highest score first, each with a date to look again.","also":["risks","risk register"]},{"id":"chgwin","g":"change","word":"Change window","text":"The times when changes may go live, such as a quiet Tuesday evening. Outside a window a change card can’t be finished, unless it is an emergency.","also":["change windows"]},{"id":"gonogo","g":"change","word":"Go / no go","text":"A quick vote just before a change goes live: each person who has to approve says Go or No go. It only goes ahead when they agree.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Approval","text":"Waiting for a yes before work starts. A card a friend raises, or a change, waits in ✅ Approvals until you approve or decline it.","also":["approvals"]},{"id":"quiettime","g":"change","word":"Quiet time","text":"A stretch of time, like a stream, a demo or the night, when nothing goes live. The teams keep working and testing, but going live waits until it ends. Elsewhere it is called a change freeze.","also":["quiet times","change freeze"]},{"id":"service","g":"run","word":"Service","text":"Something you built that people rely on, like a website or an app, looked after so it keeps working. Tick “This project is a service” and say what it offers, who uses it and who is on call.","also":["services"]},{"id":"uptime","g":"run","word":"Uptime check","text":"An automatic check, every few minutes, that your service still answers. If it fails several times in a row, AI-gile opens an incident card by itself.","also":["uptime","uptime checks"]},{"id":"statuspage","g":"run","word":"Status page","text":"A public page that shows whether a service is working (green, orange or red) with the latest update, so the people who use it can check instead of asking.","also":["status pages"]},{"id":"incident","g":"run","word":"Incident","text":"Something that is broken for the people using it right now, like the website being down. A 🔥 incident card jumps the queue: getting it working again comes first.","also":["incidents"]},{"id":"major","g":"run","word":"Major incident","text":"A big incident: many people affected, or money or data at risk. One button puts every team on it (swarm), wakes whoever is on call and asks for a status update every 30 minutes.","also":["major incidents"]},{"id":"oncall","g":"run","word":"On call","text":"Being the one who answers when something breaks, even at night. Each service has an on-call team member who is woken first for its incidents.","also":["on-call"]},{"id":"replyby","g":"run","word":"Reply-by time","text":"How long a card may wait for a first answer, for example an hour for an incident. After that it gets a red clock, so nothing is quietly forgotten. Also called a response target.","also":["reply-by times","response target","response targets"]},{"id":"postmortem","g":"run","word":"Post-mortem","text":"A short look back after an incident: what happened, what helped and what to change, without blaming anyone. An incident can’t be closed without one.","also":["post-mortems","postmortem","post-incident review"]},{"id":"problem","g":"run","word":"Problem","text":"The hidden cause behind one or more incidents. A 🧩 problem card groups incidents that keep coming back, so the cause is found and fixed for good.","also":["problems"],"noTip":1},{"id":"rootcause","g":"run","word":"Root cause","text":"The real reason something broke, not just what you saw going wrong. Fix the root cause and the incident stops coming back.","also":["root causes"]},{"id":"workaround","g":"run","word":"Workaround","text":"A way to keep things working until the real fix is ready, like restarting something when it gets stuck. It is written on the problem card so nobody has to work it out again.","also":["workarounds"]},{"id":"knownerror","g":"run","word":"Known error","text":"A problem whose cause is understood and that has a workaround, but isn’t fixed yet. 🧩 Known errors lists them, so everyone uses the workaround instead of digging again.","also":["known errors"]},{"id":"runbook","g":"run","word":"Runbook","text":"Step-by-step instructions for fixing a known kind of trouble, so it is done the same way, quickly, every time. After a big incident the team can propose one for you to OK.","also":["runbooks"]},{"id":"backup","g":"run","word":"Backup","text":"A saved copy of your data from earlier, to fall back on if something is lost or damaged. AI-gile makes a backup of your boards every day.","also":["backups","back-up","back-ups"]},{"id":"restore","g":"run","word":"Restore","text":"Putting data back from a backup. A backup only really counts once you know it can be restored, so it is worth trying now and then.","also":["restored"]},{"id":"backlog","g":"team","word":"Backlog","text":"Henüz plana alınmamış fikirler ve işler. Yapılacak'a geçene kadar orada hiçbir şey üzerinde çalışılmaz."},{"id":"sprint","g":"team","word":"Sprint","text":"Bitirilecek kartların üzerinde anlaşıldığı kısa bir çalışma dilimi (çoğunlukla bir ya da iki hafta).","also":["sprintler","sprint"]},{"id":"standup","g":"team","word":"Stand-up","text":"Kısa bir durum paylaşımı: herkes ne yaptı, sırada ne var ve onları ne engelliyor.","also":["standup","stand-up'lar","standuplar"]},{"id":"kanban","g":"team","word":"Kanban","text":"Kartların iş ilerledikçe soldan sağa geçtiği sütunlu (Yapılacak, Sürüyor, Bitti) bir pano."},{"id":"wip","g":"team","word":"WIP limiti","text":"Work in progress: bir sütunun taşıması gereken en çok kart sayısı; ekip yenisine başlamadan önce işleri bitirsin diye.","also":["WIP"]},{"id":"dod","g":"team","word":"Definition of Done","text":"The team’s short checklist of what “finished” means, like tested and explained, before a card is handed to you. Its twin, the Definition of Ready, says when a card is clear enough to start.","also":["Definition of Ready"]},{"id":"testpile","g":"team","word":"Test pile","text":"The finished cards waiting for you to try, one after another. Accept one or send it back with a note, and the next one comes up.","also":["test piles"]},{"id":"retro","g":"team","word":"Retro","text":"A look back at how the team works, to agree on one thing to do better. In AI-gile a retro suggests a change to the team’s ways of working, and you say Go or Not yet.","also":["retros","retrospective","retrospectives"]},{"id":"peerreview","g":"team","word":"Peer review","text":"A second pair of eyes: another AI checks each card’s work before it reaches you, so fewer mistakes get through.","also":["code review"]},{"id":"swarm","g":"team","word":"Swarm","text":"All hands on deck: every team drops other work to help on one urgent project until it is sorted. Other projects wait meanwhile.","also":["swarming"]},{"id":"scrummaster","g":"team","word":"Scrum Master","text":"The one who keeps the work flowing: spots stuck cards, nudges the teams and reminds you of what is waiting. In AI-gile the Lead Scrum Master does this across every project.","also":["Lead Scrum Master"]},{"id":"agent","g":"team","word":"Ajan","text":"Bir görev üzerinde kendi başına çalışan AI: kodu okur, değişiklik yapar, kontroller çalıştırır ve rapor verir.","also":["ajanlar","agent"]},{"id":"token","g":"team","word":"Token","text":"AI kullanımının sayıldığı birim: kabaca okunan ya da yazılan birkaç harflik metin. Daha az token, planından daha çok kalır.","also":["token'lar"]},{"id":"hook","g":"team","word":"Hook","text":"Belirli bir anda kendiliğinden çalışan küçük bir komut, örn. bir AI oturumu başladığında, ekip yorumlarını duysun diye.","also":["hook'lar","kanca","kancalar"]}]}};
